	/* HAD-712 (12.11.2026): Kikar HaMedina publishes no apartment list (no project_3d_units), so its showroom sends the example
	 * apartment the buyer chose as "<tower><floor>-<bearing>" (B20-276: the page's own #dira= id). The server checks the tower and
	 * the floor against the showroom's own data (assets/project-stage/hamedina/details.json, towers[*].floors) and keeps only
	 * what that says: an example apartment, its tower, its floor and the direction it faces. No rooms, no area, no price: none is
	 * published per apartment. Anything else returns null (the request is refused). */
	function nadlan_rfp_kikar_unit( $raw, $lang ) {
		if ( ! preg_match( '/^([ABC])(\d{1,2})(?:-(\d{1,3}))?$/', strtoupper( trim( (string) $raw ) ), $m ) ) { return null; }
