		if ( is_array( $j ) && ! empty( $j['towers'] ) && is_array( $j['towers'] ) ) {
			$floors = array();
			foreach ( $j['towers'] as $tk => $tv ) { if ( is_array( $tv ) && isset( $tv['floors'] ) ) { $floors[ strtoupper( (string) $tk ) ] = (int) $tv['floors']; } }
		}
		$tower = $m[1];
		$floor = (int) $m[2];
		if ( empty( $floors[ $tower ] ) || $floor < 1 || $floor > $floors[ $tower ] ) { return null; }
		$lng = in_array( $lang, array( 'he', 'fr' ), true ) ? $lang : 'en';
		$dir = '';
